K.init('mbMonod',(fig,svg)=>{
 const ol=S=>0.3*S/(0.001+S+S*S/0.5),co=S=>1.2*S/(0.5+S);
 const X0=90,X1=960,Y0=30,Y1=320,xmin=-4,xmax=2.3,sx=l=>X0+(l-xmin)/(xmax-xmin)*(X1-X0),sy=v=>Y1-v/1.3*(Y1-Y0);
 K.rngOn(fig,'mbMonS',l=>{const S=Math.pow(10,l);let h='';
  h+=R(sx(-4),Y0,sx(-1)-sx(-4),Y1-Y0,{r:0,f:'var(--blue-soft)',op:.7})+T(sx(-2.5),Y0+18,'природные олиготрофные воды',{a:'middle',s:12.5,c:'var(--phys)',w:600});
  h+=R(sx(0),Y0,sx(2)-sx(0),Y1-Y0,{r:0,f:'var(--amber-soft)',op:.7})+T(sx(1),Y0+18,'лабораторные среды',{a:'middle',s:12.5,c:'var(--chem)',w:600});
  for(let v=0;v<=1.2;v+=0.3)h+=L(X0,sy(v),X1,sy(v),{c:'var(--line)',w:1})+T(X0-10,sy(v)+5,fmt(v,1),{a:'end',s:12.5,c:'var(--muted)'});
  ['0,1 мг','1 мг','10 мг','100 мг','1 г','10 г','100 г'].forEach((t,i)=>h+=T(sx(-4+i),Y1+22,t,{a:'middle',s:12.5,c:'var(--muted)'}));
  h+=L(X0,Y1,X1,Y1,{c:'var(--muted)',w:2})+T(X1,Y1+44,'концентрация органики на литр',{a:'end',s:13,c:'var(--muted)'})+T(X0,Y0-10,'скорость роста μ, ч⁻¹',{s:13,c:'var(--muted)'});
  let a='',b='';for(let i=0;i<=200;i++){const ll=xmin+(xmax-xmin)*i/200,s=Math.pow(10,ll);a+=(i?'L':'M')+fx(sx(ll))+' '+fx(sy(ol(s)));b+=(i?'L':'M')+fx(sx(ll))+' '+fx(sy(co(s)))}
  h+=P(a,{s:'var(--phys)',w:3.5})+P(b,{s:'var(--chem)',w:3.5})+T(sx(-3.2),sy(ol(Math.pow(10,-1.6)))-4,'олиготроф',{s:14,w:700,c:'var(--phys)'})+T(sx(2.25),sy(co(150))-12,'копиотроф',{a:'end',s:14,w:700,c:'var(--chem)'});
  h+=L(sx(l),Y0,sx(l),Y1,{c:'var(--accent)',w:2,d:'4 4'})+C(sx(l),sy(ol(S)),6,{f:'var(--phys)'})+C(sx(l),sy(co(S)),6,{f:'var(--chem)'});
  put(svg,h);const o=ol(S),c=co(S);
  tx(fig).innerHTML=`<b>${o>c?'Выигрывает олиготроф':'Выигрывает копиотроф'}</b>Олиготроф: μ = ${fmt(o,2)} ч⁻¹ · копиотроф: μ = ${fmt(c,2)} ч⁻¹. `+(o>c?'Высокое сродство к субстрату решает при низких концентрациях.':o<0.09?'Олиготроф угнетён избытком субстрата — субстратное ингибирование.':'')},v=>{const S=Math.pow(10,v);return S<0.001?fmt(S*1e6,0)+' мкг/л':S<1?fmt(S*1000,S*1000<10?1:0)+' мг/л':fmt(S,S<10?1:0)+' г/л'});
});

